import React, { PureComponent } from 'react'
import { Alert, notification } from 'antd'
import { connect } from 'react-redux'
import LayoutContent from '../../../../components/utility/layoutContent'
import LayoutContentWrapper from '../../../../components/utility/layoutWrapper'
import umbrellaAction from '../../../redux/umbrella/actions'
import UmbrellaReportStyleWrapper from './gocar.style'
import GocarTable from './gocarTable'

const { getReferalData } = umbrellaAction

class UmbrellaReportList extends PureComponent {
  constructor (props) {
    super(props)
    this.state = {
      gridOptions: {
        rowData: []
      },
      paginationPageSize: 10,
      paginationNumberFormatter: function (params) {
        return '[' + params.value.toLocaleString() + ']'
      },
      agent: {},
      referred: 0,
      dataNotFound: false
    }
  }

  componentWillReceiveProps (nextProps) {
    const { referralData } = nextProps.referralList
    if (Object.keys(referralData).length > 0) {
      if (referralData.drivers.length > 0) {
        const resData = referralData.drivers.map(val => {
          return {
            name: val.name,
            phone: val.mobileNumber,
            referral_code: val.referrer,
            vehicle_plate: val.vehiclePlate,
            register_date: val.createdAt.split('T')[0]
          }
        })
        this.setState(prevState => ({
          gridOptions: {
            ...prevState.gridOptions,
            rowData: resData
          },
          dataNotFound: false,
          agent: referralData.agent,
          referred: referralData.referred,
          message: ''
        }))
      } else {
        this.setState({ dataNotFound: true })
      }
    }
  }

  onHandleChange = (val) => {
    this.setState({ [val.target.name]: val.target.value })
  }

  dataNotFoundAlert = () => {
    return (
      <LayoutContentWrapper style={{ paddingTop: '0px' }}>
        <LayoutContent style={{ padding: '6vh' }}>
          <h3>Gocar Komplit List</h3>
          <Alert
            message='Not Found!'
            description='Gocar Driver not found!'
            type='warning'
            onClose={(e) => {}}
            style={{ padding: '20px' }}
          />
        </LayoutContent>
      </LayoutContentWrapper>
    )
  }

  openNotificationNotFoundReferrer = () => {
    notification['warning']({
      message: 'Driver not found',
      description: 'Driver is not found!'
    })
  };

  render () {
    return (
      <UmbrellaReportStyleWrapper>
        <GocarTable {...this.props} />
      </UmbrellaReportStyleWrapper>
    )
  }
}

export default connect(
  state => ({
    referralList: state.Umbrella
  }),
  { getReferalData }
)(UmbrellaReportList)
